from pathlib import Path

p=Path("index.html")
s=p.read_text(encoding="utf-8")
marker='<style id="mws-v57-style">'
if marker in s:
    print("v5.7 already applied")
else:
    patch = '\n<style id="mws-v57-style">\n.post-minigame-entry-v57{display:flex;align-items:center;gap:12px;padding-left:16px;margin-left:6px;border-left:1px solid color-mix(in srgb,var(--border) 86%, transparent);order:3}\n.post-mini-game-btn-v57{min-height:42px;padding:9px 16px;border-radius:12px;border:1px solid rgba(74,222,128,.38);background:linear-gradient(135deg,rgba(16,185,129,.18),rgba(45,212,191,.14));color:#d7fff0;font-weight:950;letter-spacing:-.01em;box-shadow:0 12px 28px rgba(16,185,129,.14), inset 0 1px 0 rgba(255,255,255,.05);transition:transform .16s ease,filter .16s ease,box-shadow .16s ease,border-color .16s ease;white-space:nowrap}\n.post-mini-game-btn-v57:hover{transform:translateY(-1px);filter:brightness(1.06);border-color:rgba(110,231,183,.55);box-shadow:0 16px 34px rgba(16,185,129,.2),0 0 18px rgba(45,212,191,.18)}\n.post-mini-game-btn-v57:active{transform:translateY(0) scale(.985)}\n.post-mini-game-btn-v57::before{content:\'▶\';display:inline-block;margin-right:8px;font-size:12px;opacity:.85}\n.post-view-controls .post-column-control{order:4}\n@media(max-width:980px){.post-minigame-entry-v57{order:4;width:100%;margin-left:0;padding-left:0;border-left:0;padding-top:4px}.post-mini-game-btn-v57{width:100%}.post-view-controls .post-column-control{order:5}}\n.post-game-card.recommended{position:relative;overflow:hidden;border-color:rgba(250,204,21,.48);background:radial-gradient(circle at 78% 22%,rgba(250,204,21,.12),transparent 32%),linear-gradient(180deg,rgba(255,235,140,.03),rgba(124,58,237,.04)),var(--input);box-shadow:0 16px 38px rgba(250,204,21,.09),0 0 0 1px rgba(250,204,21,.08) inset}\n.post-game-card.recommended:hover:not(:disabled){border-color:rgba(251,191,36,.72);box-shadow:0 18px 44px rgba(250,204,21,.16),0 0 22px rgba(244,114,182,.18),0 0 0 1px rgba(251,191,36,.18) inset}\n.post-game-card.recommended::after{content:\'\';position:absolute;inset:-28% auto auto 58%;width:150px;height:150px;background:radial-gradient(circle,rgba(255,255,255,.28),rgba(250,204,21,.12) 28%,transparent 70%);filter:blur(6px);opacity:.82;animation:mwsV57RecommendedGlow 3.1s ease-in-out infinite;pointer-events:none}\n.post-game-best-ribbon-v57{position:absolute;top:0;left:0;padding:6px 14px 6px 12px;border-radius:14px 0 14px 0;background:linear-gradient(135deg,#fde047,#f59e0b);color:#2b1800;font-size:11px;font-weight:1000;letter-spacing:.04em;box-shadow:0 10px 26px rgba(245,158,11,.25);z-index:2}\n.post-game-rec-chip-v57{display:inline-flex;align-items:center;gap:4px;margin-top:10px;padding:5px 9px;border-radius:999px;border:1px solid rgba(251,191,36,.35);background:rgba(251,191,36,.1);font-size:11px;font-weight:850;color:#ffeab2}\n.post-game-card-title-wrap-v57{display:flex;align-items:center;justify-content:space-between;gap:10px}\n.post-game-card-title-wrap-v57 .post-game-card-title{margin-top:0}\n.post-game-picker-box .post-game-card{position:relative}\n@keyframes mwsV57RecommendedGlow{0%,100%{transform:translate3d(0,0,0) scale(1);opacity:.55}50%{transform:translate3d(0,6px,0) scale(1.08);opacity:.92}}\n.post-schedule-notice-modal-v57{z-index:1150!important}\n.post-schedule-notice-box-v57{width:min(560px,94vw)!important;border-radius:22px!important;padding:22px!important;background:linear-gradient(180deg,rgba(19,27,53,.98),rgba(11,17,36,.99))!important;border:1px solid rgba(96,165,250,.26)!important;box-shadow:0 28px 68px rgba(0,0,0,.45),0 0 0 1px rgba(129,140,248,.08) inset}\n.post-schedule-notice-kicker-v57{font-size:11px;letter-spacing:.18em;font-weight:900;color:#7dd3fc;margin-bottom:8px}\n.post-schedule-notice-title-v57{font-size:31px;font-weight:1000;line-height:1.1;margin:0 0 12px}\n.post-schedule-notice-body-v57{font-size:15px;line-height:1.75;color:#dbe6ff}\n.post-schedule-notice-body-v57 strong{color:#ffffff}\n.post-schedule-notice-check-v57{display:flex;align-items:center;gap:10px;margin-top:16px;padding:12px 14px;border-radius:14px;border:1px solid rgba(99,102,241,.22);background:rgba(99,102,241,.08);cursor:pointer}\n.post-schedule-notice-check-v57 input{width:17px;height:17px}\n.post-schedule-notice-actions-v57{display:flex;justify-content:flex-end;gap:10px;margin-top:18px;flex-wrap:wrap}\n.post-schedule-notice-ok-v57{min-width:112px;padding:11px 16px;border-radius:12px;border:1px solid rgba(56,189,248,.28);background:linear-gradient(135deg,rgba(59,130,246,.92),rgba(6,182,212,.95));color:#fff;font-weight:950;box-shadow:0 14px 34px rgba(37,99,235,.22)}\n.post-schedule-notice-sub-v57{font-size:12px;color:var(--muted);margin-top:12px}\n</style>\n<script id="mws-v57-script">\n(function(){\n  if(window.__mwsV57Loaded)return; window.__mwsV57Loaded=true;\n\n  function ensureMiniGameButtonV57(){\n    const controls=document.querySelector(\'#postApplicantsPanel .post-view-controls\');\n    const column=document.querySelector(\'#postApplicantsPanel .post-column-control\');\n    if(!controls||!column)return;\n    let btn=document.getElementById(\'postRandomGameBtn\');\n    if(!btn){\n      btn=document.createElement(\'button\');\n      btn.id=\'postRandomGameBtn\';\n      btn.type=\'button\';\n    }\n    btn.textContent=\'미니게임 진행하기\';\n    btn.className=\'post-mini-game-btn-v57\';\n    btn.onclick=()=>{ if(typeof window.openPostGamePicker===\'function\') window.openPostGamePicker(); };\n    let wrap=document.getElementById(\'postMiniGameEntryV57\');\n    if(!wrap){\n      wrap=document.createElement(\'div\');\n      wrap.id=\'postMiniGameEntryV57\';\n      wrap.className=\'post-minigame-entry-v57\';\n    }\n    if(btn.parentElement!==wrap)wrap.appendChild(btn);\n    if(wrap.parentElement!==controls)controls.insertBefore(wrap,column);\n  }\n\n  window.openPostGamePicker=function(){\n    const p=postById(activePostId); if(!p)return;\n    const arr=uniquePostGameApplicants(p), modal=document.getElementById(\'postGamePickerModal\');\n    const subtitle=document.getElementById(\'postGamePickerSubtitle\');\n    if(subtitle)subtitle.textContent=`${p.name} · 가챠 상태 게임 참가 대상 ${arr.length}명 (확정 / 대기 / 다음기회에 / 중복 작성자 제외)`;\n    const grid=document.getElementById(\'postGamePickerGrid\');\n    if(grid){\n      grid.innerHTML=Object.entries(POST_GAME_DEFS).map(([key,g])=>{\n        const tooMany=arr.length>g.cap, disabled=arr.length<2||tooMany;\n        const recommended=key===\'multiDraw\';\n        return `<button class="post-game-card ${recommended?\'recommended\':\'\'}" ${disabled?\'disabled\':\'\'} onclick="launchPostApplicantsIntoGame(\'${key}\')">${recommended?\'<span class="post-game-best-ribbon-v57">Best</span>\':\'\'}<div class="post-game-card-kicker">MINI GAME</div><div class="post-game-card-title-wrap-v57"><div class="post-game-card-title">${g.title}</div>${recommended?\'<span class="post-game-rec-chip-v57">추천 선택</span>\':\'\'}</div><div class="post-game-card-desc">${g.desc}</div><div class="post-game-card-cap">${tooMany?`현재 ${arr.length}명 · 최대 ${g.cap}명이라 사용 불가`:`가챠 ${arr.length}명 준비 · 최대 ${g.cap}명`}</div></button>`;\n      }).join(\'\');\n    }\n    modal?.classList.add(\'open\');\n    modal?.setAttribute(\'aria-hidden\',\'false\');\n    try{syncModalInteractionState()}catch(_){ }\n  };\n\n  function ensureScheduleNoticeModalV57(){\n    let modal=document.getElementById(\'postScheduleNoticeModalV57\');\n    if(modal)return modal;\n    modal=document.createElement(\'div\');\n    modal.id=\'postScheduleNoticeModalV57\';\n    modal.className=\'modal post-schedule-notice-modal-v57\';\n    modal.setAttribute(\'aria-hidden\',\'true\');\n    modal.innerHTML=`<div class="modalbox post-schedule-notice-box-v57"><div class="post-schedule-notice-kicker-v57">CONTENT SCHEDULE GUIDE</div><h2 class="post-schedule-notice-title-v57">참여자 자동 등록 안내</h2><div class="post-schedule-notice-body-v57">이 게시글에서 <strong>확정</strong>을 누른 인원들은 컨텐츠 일정 추가 창의 <strong>참여자</strong>에 자동으로 등록됩니다.<br>반대로 <strong>가챠</strong>, <strong>대기</strong>, <strong>다음기회에</strong> 상태 인원은 자동 등록되지 않습니다.</div><label class="post-schedule-notice-check-v57"><input type="checkbox" id="postScheduleNoticeDontShowV57"><span>이 메세지를 다시 보지 않기</span></label><div class="post-schedule-notice-sub-v57">이 설정은 현재 브라우저에 저장됩니다.</div><div class="post-schedule-notice-actions-v57"><button type="button" class="ghost" id="postScheduleNoticeCloseBtnV57">닫기</button><button type="button" class="post-schedule-notice-ok-v57" id="postScheduleNoticeOkBtnV57">확인</button></div></div>`;\n    modal.addEventListener(\'click\',e=>{if(e.target===modal)window.closePostScheduleNoticeV57()});\n    document.body.appendChild(modal);\n    modal.querySelector(\'#postScheduleNoticeCloseBtnV57\')?.addEventListener(\'click\',()=>window.closePostScheduleNoticeV57());\n    modal.querySelector(\'#postScheduleNoticeOkBtnV57\')?.addEventListener(\'click\',()=>window.closePostScheduleNoticeV57());\n    return modal;\n  }\n\n  window.closePostScheduleNoticeV57=function(){\n    const modal=document.getElementById(\'postScheduleNoticeModalV57\');\n    const check=document.getElementById(\'postScheduleNoticeDontShowV57\');\n    try{ if(check?.checked) localStorage.setItem(\'mws_hide_post_schedule_notice_v57\',\'1\'); }catch(_){ }\n    modal?.classList.remove(\'open\');\n    modal?.setAttribute(\'aria-hidden\',\'true\');\n    try{syncModalInteractionState()}catch(_){ }\n  };\n\n  window.showPostScheduleNoticeV57=function(){\n    try{ if(localStorage.getItem(\'mws_hide_post_schedule_notice_v57\')===\'1\') return; }catch(_){ }\n    const modal=ensureScheduleNoticeModalV57();\n    const check=document.getElementById(\'postScheduleNoticeDontShowV57\');\n    if(check)check.checked=false;\n    modal.classList.add(\'open\');\n    modal.setAttribute(\'aria-hidden\',\'false\');\n    try{syncModalInteractionState()}catch(_){ }\n  };\n\n  if(typeof window.openPostAsContentSchedule===\'function\' && !window.__mwsV57WrappedSchedule){\n    const baseOpenPostAsContentSchedule=window.openPostAsContentSchedule;\n    window.__mwsV57WrappedSchedule=true;\n    window.openPostAsContentSchedule=function(){\n      const out=baseOpenPostAsContentSchedule.apply(this,arguments);\n      setTimeout(()=>{ try{window.showPostScheduleNoticeV57()}catch(_){ } },90);\n      return out;\n    };\n    try{ openPostAsContentSchedule=window.openPostAsContentSchedule; }catch(_){ }\n  }\n\n  if(typeof window.renderPosts===\'function\' && !window.__mwsV57WrappedRenderPosts){\n    const baseRenderPostsV57=window.renderPosts;\n    window.__mwsV57WrappedRenderPosts=true;\n    window.renderPosts=function(){\n      const out=baseRenderPostsV57.apply(this,arguments);\n      setTimeout(ensureMiniGameButtonV57,0);\n      return out;\n    };\n    try{ renderPosts=window.renderPosts; }catch(_){ }\n  }\n\n  document.addEventListener(\'keydown\',e=>{\n    if(e.key===\'Escape\' && document.getElementById(\'postScheduleNoticeModalV57\')?.classList.contains(\'open\')){\n      e.preventDefault();\n      window.closePostScheduleNoticeV57();\n    }\n  }, true);\n\n  if(document.readyState===\'loading\')document.addEventListener(\'DOMContentLoaded\',()=>setTimeout(ensureMiniGameButtonV57,0));\n  else setTimeout(ensureMiniGameButtonV57,0);\n})();\n</script>\n\n'
    if "</body>" not in s:
        raise SystemExit("No </body> tag")
    s=s.replace("</body>", patch+"\n</body>", 1)
    p.write_text(s,encoding="utf-8")
    print("Applied v5.7")
